package com.auraboot.framework.file.security;

import com.auraboot.framework.meta.service.impl.CommandPublicOutputProjectionPlan;
import com.auraboot.framework.plugin.extension.BusinessResourceAuthorization;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.security.access.AccessDeniedException;

import java.util.Map;
import java.util.Objects;

/** Host-owned provenance for immutable generated bytes; never an upload DTO. */
public record BusinessArtifactAuthorization(int version, Long tenantId, String commandCode, String rootModel,
        String rootPid, String rootField, String fingerprint, Map<String, CommandPublicOutputProjectionPlan.ModelFields> models,
        Map<String, String> rootBinding) {
    private static final int MAX_ENCODED_LENGTH = 262_144;
    private static final ObjectMapper JSON = new ObjectMapper()
            .enable(com.fasterxml.jackson.core.JsonParser.Feature.STRICT_DUPLICATE_DETECTION)
            .enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES)
            .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);

    public BusinessArtifactAuthorization {
        if (version != 1 || tenantId == null || tenantId <= 0 || commandCode == null || commandCode.isBlank()
                || commandCode.length() > 128 || rootPid == null || !rootPid.matches("[0-9A-HJKMNP-TV-Z]{26}")
                || fingerprint == null || !fingerprint.matches("[0-9a-f]{64}")) throw denied();
        BusinessResourceAuthorization.identifier(rootModel); BusinessResourceAuthorization.identifier(rootField);
        models = Map.copyOf(models);
        rootBinding = rootBinding == null ? Map.of() : Map.copyOf(rootBinding);
        if (rootBinding.size() > 16) throw denied();
        rootBinding.forEach((field, hash) -> {
            BusinessResourceAuthorization.identifier(field);
            if (hash == null || !hash.matches("[0-9a-f]{64}")) throw denied();
        });
        if (models.isEmpty() || models.size() > 16 || !models.containsKey(rootModel)
                || !models.get(rootModel).declared().contains(rootField)) throw denied();
        models.forEach((model, fields) -> {
            BusinessResourceAuthorization.identifier(model);
            if (fields.declared().size() > 128 || fields.policyMasks().size() > 256 || fields.detailMasks().size() > 256) throw denied();
            fields.declared().forEach(BusinessResourceAuthorization::identifier);
        });
        if (!fingerprint.equals(new CommandPublicOutputProjectionPlan(null, null, models).fingerprint())) throw denied();
    }

    public static BusinessArtifactAuthorization capture(CommandPublicOutputProjectionPlan plan, String field) {
        return capture(plan, field, Map.of());
    }

    public static BusinessArtifactAuthorization capture(CommandPublicOutputProjectionPlan plan, String field, Map<String,String> binding) {
        var root = Objects.requireNonNull(plan.target());
        return new BusinessArtifactAuthorization(1, root.tenantId(), root.commandCode(), root.modelCode(), root.targetRecordId(),
                field, plan.fingerprint(), plan.models(), binding);
    }

    /** Hash typed scalar facts without placing their raw values in public file metadata. */
    public static Map<String,String> binding(java.util.Set<String> fields, Map<String,Object> root) {
        if (fields == null || fields.size() > 16 || root == null) throw denied();
        Map<String,String> result = new java.util.TreeMap<>();
        fields.forEach(field -> {
            BusinessResourceAuthorization.identifier(field);
            Object value = root.get(field);
            if (!(value == null || value instanceof String || value instanceof Boolean || value instanceof Number)
                    || value instanceof String text && text.length() > 4_096) throw denied();
            String type = value == null ? "null" : value instanceof Number ? "number" : value instanceof Boolean ? "boolean" : "string";
            String canonical = value == null ? "" : value instanceof Number number
                    ? new java.math.BigDecimal(number.toString()).stripTrailingZeros().toPlainString() : value.toString();
            try {
                byte[] encoded = JSON.writeValueAsBytes(java.util.List.of(1, field, type, canonical));
                result.put(field, java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(encoded)));
            } catch (JsonProcessingException | java.security.NoSuchAlgorithmException failure) {
                throw new IllegalStateException("Cannot bind business artifact root facts", failure);
            }
        });
        return Map.copyOf(result);
    }

    public String encode() {
        try {
            String encoded = JSON.writeValueAsString(this);
            if (encoded.length() > MAX_ENCODED_LENGTH) throw denied();
            return encoded;
        }
        catch (JsonProcessingException failure) { throw new IllegalStateException("Cannot encode business artifact provenance", failure); }
    }

    public static BusinessArtifactAuthorization parse(String value) {
        if (value == null || value.isBlank() || value.length() > MAX_ENCODED_LENGTH) throw denied();
        try { return JSON.readValue(value, BusinessArtifactAuthorization.class); }
        catch (JsonProcessingException | IllegalArgumentException failure) { throw denied(); }
    }

    /** Broader visibility may consume old restricted bytes; new restrictions require regeneration. */
    public boolean permits(CommandPublicOutputProjectionPlan current) {
        if (!models.keySet().equals(current.models().keySet())) return false;
        for (var entry : models.entrySet()) {
            var before = entry.getValue(); var now = current.models().get(entry.getKey());
            if (!before.declared().equals(now.declared()) || !now.readable().containsAll(before.readable())) return false;
            for (String field : before.readable()) {
                var policy = now.policyMasks().stream().filter(mask -> field.equals(mask.field())).toList();
                var detail = now.detailMasks().stream().filter(mask -> field.equals(mask.field())).toList();
                if ((!policy.isEmpty() || !detail.isEmpty())
                        && (!policy.equals(before.policyMasks().stream().filter(mask -> field.equals(mask.field())).toList())
                        || !detail.equals(before.detailMasks().stream().filter(mask -> field.equals(mask.field())).toList()))) return false;
            }
        }
        return true;
    }

    static AccessDeniedException denied() { return new AccessDeniedException("Business artifact access is unavailable under the current authorization"); }
}
